import React, { useEffect, useState } from "react";
import { db } from "../firebase";
import { collection, getDocs, query, orderBy, doc, addDoc, deleteDoc } from "firebase/firestore";
import { useNavigate } from "react-router-dom";
import { Check, Trash2, Plus, Search, X } from "lucide-react";
import MySpaceSubmitForm from "./MySpaceSubmitForm";

export default function MySpace() {
  const [writings, setWritings] = useState([]);
  const [pendingWritings, setPendingWritings] = useState([]);
  const [showAdmin, setShowAdmin] = useState(false);
  const [showSubmitForm, setShowSubmitForm] = useState(false);
  const [showSearch, setShowSearch] = useState(false);
  const [searchQuery, setSearchQuery] = useState("");
  const navigate = useNavigate();

  useEffect(() => {
    fetchWritings();
  }, []);

  const fetchWritings = async () => {
    // Fetch published writings from myspace collection
    const publishedQuery = query(
      collection(db, "myspace"),
      orderBy("createdAt", "desc")
    );
    const publishedSnapshot = await getDocs(publishedQuery);
    const publishedData = publishedSnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));
    setWritings(publishedData.filter(item => item.published !== false));

    // Fetch pending writings from myspacerequests collection
    const pendingQuery = query(
      collection(db, "myspacerequests"),
      orderBy("createdAt", "desc")
    );
    const pendingSnapshot = await getDocs(pendingQuery);
    const pendingData = pendingSnapshot.docs.map((doc) => ({
      id: doc.id,
      ...doc.data(),
    }));
    setPendingWritings(pendingData.filter(item => item.published === false));
  };

  const handleApprove = async (id) => {
    try {
      // Get the document from myspacerequests
      const pendingDoc = pendingWritings.find(w => w.id === id);
      if (!pendingDoc) return;

      // Add to myspace collection
      await addDoc(collection(db, "myspace"), {
        ...pendingDoc,
        published: true,
        publishedAt: new Date(),
      });

      // Delete from myspacerequests
      await deleteDoc(doc(db, "myspacerequests", id));
      
      alert("✅ Writing approved and published!");
      fetchWritings();
    } catch (error) {
      console.error("Error approving:", error);
      alert("❌ Failed to approve writing");
    }
  };

  const handleReject = async (id) => {
    if (!window.confirm("Are you sure you want to delete this submission?")) return;
    
    try {
      await deleteDoc(doc(db, "myspacerequests", id));
      alert("✅ Writing deleted");
      fetchWritings();
    } catch (error) {
      console.error("Error deleting:", error);
      alert("❌ Failed to delete writing");
    }
  };

  // Filter writings based on search query
  const filteredWritings = writings.filter((item) => {
    if (!searchQuery.trim()) return true;
    
    const query = searchQuery.toLowerCase();
    return (
      item.title?.toLowerCase().includes(query) ||
      item.author?.toLowerCase().includes(query) ||
      item.short?.toLowerCase().includes(query) ||
      item.full?.toLowerCase().includes(query) ||
      item.type?.toLowerCase().includes(query) ||
      item.designation?.toLowerCase().includes(query) ||
      item.college?.toLowerCase().includes(query)
    );
  });

  return (
    <div className="min-h-screen mt-20 bg-white p-6">
      {/* Header with Search and Add Buttons */}
      <div className="max-w-3xl mx-auto mb-10">
        <div className="flex items-center justify-center gap-4">
          {/* Search Button on Far Left */}
          <button
            onClick={() => {
              setShowSearch(!showSearch);
              if (showSearch) setSearchQuery("");
            }}
            className="bg-black hover:bg-gray-800 text-white p-3 rounded-full shadow-lg hover:scale-110 transition-all transform"
            title="Search Writings"
          >
            {showSearch ? <X size={28} strokeWidth={3} /> : <Search size={28} strokeWidth={3} />}
          </button>

          {/* Add Button */}
          <button
            onClick={() => setShowSubmitForm(true)}
            className="bg-black mr-10 hover:bg-gray-800 text-white p-3 rounded-full shadow-lg hover:scale-110 transition-all transform"
            title="Submit Your Writing"
          >
            <Plus size={28} strokeWidth={3} />
          </button>

          {/* Main Heading */}
          <div className="text-center">
            <h1 className="text-4xl font-bold">MySpace</h1>
            <p className="text-lg mt-2">
              Selected writings from our community
            </p>
          </div>
        </div>

        {/* Search Bar - Shows when search button clicked */}
        {showSearch && (
          <div className="mt-6 animate-fadeIn">
            <input
              type="text"
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              placeholder="Search by title, author, content, type..."
              className="w-full px-6 py-4 text-lg border-2 border-gray-300 rounded-xl focus:border-black focus:outline-none transition-colors"
              autoFocus
            />
            {searchQuery && (
              <p className="mt-2 text-sm text-gray-600 text-center">
                Found {filteredWritings.length} result{filteredWritings.length !== 1 ? 's' : ''}
              </p>
            )}
          </div>
        )}
      </div>

      {/* Admin Panel - Full Content Display */}
      {showAdmin && pendingWritings.length > 0 && (
        <div className="max-w-4xl mx-auto mb-8 bg-yellow-50 border border-yellow-300 rounded-xl p-6">
          <h2 className="text-2xl font-bold mb-4">Pending Approvals ({pendingWritings.length})</h2>
          
          <div className="space-y-6">
            {pendingWritings.map((item) => (
              <div
                key={item.id}
                className="bg-white border border-gray-300 rounded-lg p-6"
              >
                <div className="flex justify-between items-start mb-4">
                  <div className="flex-1">
                    <h3 className="text-2xl font-bold mb-2">{item.title}</h3>
                    <p className="text-sm mb-1">
                      By <strong>{item.author}</strong> • {item.type}
                    </p>
                    <p className="text-xs text-gray-600 mb-3">
                      {item.designation} • {item.college}
                    </p>
                  </div>
                  
                  <div className="flex gap-2 ml-4">
                    <button
                      onClick={() => handleApprove(item.id)}
                      className="bg-green-600 text-white p-2 rounded-lg hover:bg-green-700"
                      title="Approve & Publish"
                    >
                      <Check size={20} />
                    </button>
                    <button
                      onClick={() => handleReject(item.id)}
                      className="bg-red-600 text-white p-2 rounded-lg hover:bg-red-700"
                      title="Delete"
                    >
                      <Trash2 size={20} />
                    </button>
                  </div>
                </div>

                {/* Full Content */}
                <div className="prose max-w-none">
                  <div className="text-gray-800 whitespace-pre-wrap leading-relaxed">
                    {item.full}
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Admin Toggle - Small button at bottom of page */}
      {pendingWritings.length > 0 && (
        <div className="max-w-4xl mx-auto mb-6 text-center">
          <button
            onClick={() => setShowAdmin(!showAdmin)}
            className="text-sm text-gray-600 hover:text-gray-900 underline"
          >
            {showAdmin ? "Hide" : "Show"} Admin Panel ({pendingWritings.length} pending)
          </button>
        </div>
      )}

      {/* Published Cards */}
      <div className="max-w-4xl mx-auto grid gap-6">
        {filteredWritings.length > 0 ? (
          filteredWritings.map((item) => (
            <div
              key={item.id}
              onClick={() => navigate(`/myspace/${item.id}`)}
              className="border border-black rounded-xl p-6 cursor-pointer hover:bg-gray-50"
            >
              <h2 className="text-2xl font-semibold mb-1">
                {item.title}
              </h2>

              <p className="text-sm mb-2">
                By <strong>{item.author}</strong> • {item.type}
              </p>

              <p className="text-gray-700 leading-relaxed">
                {item.short}
              </p>

              <span className="inline-block mt-4 text-sm font-semibold underline">
                Read more →
              </span>
            </div>
          ))
        ) : searchQuery ? (
          <div className="text-center py-12 text-gray-500">
            <Search size={48} className="mx-auto mb-4 opacity-30" />
            <p className="text-xl">No results found for "{searchQuery}"</p>
            <p className="text-sm mt-2">Try different keywords</p>
          </div>
        ) : null}
      </div>

      {/* Submit Form Modal */}
      {showSubmitForm && (
        <MySpaceSubmitForm onClose={() => setShowSubmitForm(false)} />
      )}

      <style jsx>{`
        @keyframes fadeIn {
          from {
            opacity: 0;
            transform: translateY(-10px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .animate-fadeIn {
          animation: fadeIn 0.3s ease-out;
        }
      `}</style>
    </div>
  );
}